import sys

def solve() -> None:
    n = int(sys.stdin.readline())
    strings = [sys.stdin.readline().strip() for _ in range(n)]

    min_moves = float('inf')

    # Try rotating each string as the target
    for i, target in enumerate(strings):
        total_moves = 0

        # Check if all strings can be rotated to match this target
        valid = True
        for j, s in enumerate(strings):
            # Find the minimum moves to rotate s to match target
            found = False
            for moves in range(len(s)):
                if s[moves:] + s[:moves] == target:
                    total_moves += moves
                    found = True
                    break
            if not found:
                valid = False
                break

        if valid:
            min_moves = min(min_moves, total_moves)

    print(min_moves if min_moves != float('inf') else -1)

if __name__ == "__main__":
    solve()
"}

