import math

def lcm(a, b):
    return a * b // math.gcd(a, b)

def max_lcm(n):
    if n == 1:
        return 1
    if n == 2:
        return 2

    # Try different combinations
    candidates = []

    # LCM(n, n-1, n-2)
    candidates.append(lcm(lcm(n, n-1), n-2))

    # LCM(n, n-1, n-3)
    candidates.append(lcm(lcm(n, n-1), n-3))

    # LCM(n, n-2, n-3)
    candidates.append(lcm(lcm(n, n-2), n-3))

    # LCM(n-1, n-2, n-3)
    candidates.append(lcm(lcm(n-1, n-2), n-3))

    # Special case: n is even, try LCM(n, n-1, n/2)
    if n % 2 == 0:
        candidates.append(lcm(lcm(n, n-1), n//2))

    return max(candidates)

n = int(input())
print(max_lcm(n))
"}

