def min_toggles_to_compress(n, m, grid):
    min_toggles = float('inf')

    # Try all possible k values
    for k in range(2, n + 1):
        # Pad the grid to dimensions divisible by k
        rows = n + (k - n % k) % k
        cols = m + (k - m % k) % k

        # Create padded grid with zeros
        padded_grid = [[0 for _ in range(cols)] for _ in range(rows)]

        # Fill in original grid values
        for i in range(n):
            for j in range(m):
                padded_grid[i][j] = int(grid[i][j])

        # Count 0s and 1s in the padded grid
        zero_count = 0
        one_count = 0

        for i in range(rows):
            for j in range(cols):
                if padded_grid[i][j] == 0:
                    zero_count += 1
                else:
                    one_count += 1

        # Divide into k x k blocks
        num_blocks_row = rows // k
        num_blocks_col = cols // k

        # Count toggles needed
        toggles = 0

        for i in range(num_blocks_row):
            for j in range(num_blocks_col):
                # Count 0s and 1s in this block
                block_zero = 0
                block_one = 0

                for x in range(i * k, (i + 1) * k):
                    for y in range(j * k, (j + 1) * k):
                        if padded_grid[x][y] == 0:
                            block_zero += 1
                        else:
                            block_one += 1

                toggles += min(block_zero, block_one)

        min_toggles = min(min_toggles, toggles)

    return min_toggles

# Read input
n, m = map(int, input().split())
grid = []
for _ in range(n):
    grid.append(input().strip())

# Calculate and print result
print(min_toggles_to_compress(n, m, grid))
