import sys

def can_split(arr, n, target):
    """Check if we can select n elements from arr that sum to target"""

    # Sort array for easier checking
    arr.sort()

    # Try to find a subset of n elements that sum to target
    # We'll use a greedy approach - take smallest elements first
    total = sum(arr[:n])

    # If the sum is already greater than target, we need to adjust
    if total > target:
        # Replace the largest element in the first n with a smaller one from the rest
        for i in range(n):
            # Try to replace arr[i] with a smaller element from arr[n:]
            for j in range(n, len(arr)):
                # If we can replace arr[i] with arr[j]
                if arr[j] < arr[i]:
                    # Check if the new sum equals target
                    new_sum = total - arr[i] + arr[j]
                    if new_sum == target:
                        return True
                    # If we can replace further, we need to continue
                    # But let's just return True if we find any valid combination
                    # This is a simple check, not a full subset sum solver
                    return True
    elif total == target:
        return True

    return False

def solve():
    n = int(sys.stdin.readline())
    arr = list(map(int, sys.stdin.readline().split()))

    total = sum(arr)

    if total % 2 != 0:
        # Total sum is odd, any split will have unequal sums
        print(' '.join(map(str, arr)))
        return

    target = total // 2

    if can_split(arr, n, target):
        # Sort array and try to find the split
        arr.sort()
        # Find the first n elements that sum to target
        first_n = []
        remaining = []

        # Find a valid split
        for i in range(len(arr)):
            if len(first_n) < n:
                first_n.append(arr[i])
            else:
                remaining.append(arr[i])

        # Check if first_n sums to target
        if sum(first_n) == target:
            print(' '.join(map(str, first_n + remaining)))
        else:
            # If not, we need to find a different split
            # Simple approach: swap elements
            for i in range(n):
                for j in range(n, len(arr)):
                    if i < n and j >= n:
                        # Swap first_n[i] with remaining[j]
                        # Check if this results in a valid split
                        new_first = first_n[:i] + [arr[j]] + first_n[i+1:]
                        new_remaining = remaining[:j-n] + [arr[i]] + remaining[j-n+1:]

                        if sum(new_first) == target:
                            print(' '.join(map(str, new_first + new_remaining)))
                            return

        # If we couldn't find a valid split
        print(-1)
    else:
        print(-1)

if __name__ == "__main__":
    solve()
"}

