import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    idx = 0
    n = int(data[idx]); idx += 1
    m = int(data[idx]); idx += 1
    w = int(data[idx]); idx += 1

    weights = list(map(int, data[idx:idx+n])); idx += n
    beauties = list(map(int, data[idx:idx+n])); idx += n

    # Union-Find for friendship groups
    parent = list(range(n))

    def find(u):
        if parent[u] != u:
            parent[u] = find(parent[u])
        return parent[u]

    def union(u, v):
        parent[find(u)] = find(v)

    for _ in range(m):
        u = int(data[idx]) - 1; idx += 1
        v = int(data[idx]) - 1; idx += 1
        union(u, v)

    # Group Hoses by root
    groups = {}
    for i in range(n):
        r = find(i)
        if r not in groups:
            groups[r] = []
        groups[r].append(i)

    # DP
    dp = [-1] * (w + 1)
    dp[0] = 0

    for group in groups.values():
        # Calculate total if all taken
        total_weight = sum(weights[i] for i in group)
        total_beauty = sum(beauties[i] for i in group)

        # Option 1: Take all (if possible)
        if total_weight <= w:
            for j in range(w, total_weight - 1, -1):
                if dp[j - total_weight] != -1:
                    if dp[j] < dp[j - total_weight] + total_beauty:
                        dp[j] = dp[j - total_weight] + total_beauty

        # Option 2: Take at most one from group (0-1 knapsack)
        for i in range(len(group)):
            wi = weights[group[i]]
            bi = beauties[group[i]]

            if wi > w:
                continue

            for j in range(w, wi - 1, -1):
                if dp[j - wi] != -1:
                    if dp[j] < dp[j - wi] + bi:
                        dp[j] = dp[j - wi] + bi

    max_beauty = max(dp)
    print(max_beauty)

if __name__ == "__main__":
    solve()
"}

