import itertools


def generate_super_lucky(length):
    """Generate all super lucky numbers with the given length"""
    half = length // 2
    digits = ['4'] * half + ['7'] * half
    super_lucky = []

    # Generate all permutations of these digits
    for perm in set(itertools.permutations(digits)):
        super_lucky.append(''.join(perm))

    return sorted(super_lucky)

n_str = input().strip()

# Find the smallest super lucky number that is >= n
answer = None

# Try all even lengths starting from 2
length = len(n_str)
for candidate_length in range(2, length + 4, 2):
    candidates = generate_super_lucky(candidate_length)

    # Find the minimum candidate that is >= n_str
    min_cand = None
    for cand in candidates:
        # If candidates and n have different lengths, the shorter one is smaller
        if len(cand) > len(n_str):
            if min_cand is None or cand < min_cand:
                min_cand = cand
        elif len(cand) < len(n_str):
            continue
        else:  # same length
            if cand >= n_str:
                if min_cand is None or cand < min_cand:
                    min_cand = cand

    if min_cand is not None:
        answer = min_cand
        break

print(answer)
