import sys

def max_score(n):
    """Calculate the maximum score for given n."""
    score = 0

    # Consider all possible starting values a with 2 <= |a| <= n
    for a in range(-n, 0, -1):
        if abs(a) >= 2:
            # Check all possible multiples b = a * k where k > 1
            for k in range(2, n // abs(a) + 1):
                b = a * k
                # Only add if the transformation is valid and we haven't already counted it
                # Since we iterate in order, we only count each base once
                if b <= n:
                    score += k
                if -b >= -n:
                    score += k

    return score

# Read input
