import sys

def max_score(n):
    """Calculate the maximum score for given n."""
    score = 0

    # Consider all possible transformations
    # We can transform a to b where b = a * x for some x with |x| > 1
    # And b must be in [-n, -2] ∪ [2, n]

    # Let's consider all possible a and b in the range [-n, -2] ∪ [2, n]
    for a in range(-n, 0, -1):
        if abs(a) >= 2:
            # Transform a to b where b = a * x for x > 1
            for b in range(2 * abs(a), n + 1, abs(a)):
                if abs(b) >= 2:
                    score += abs(b / a)

            # Transform a to b where b = a * x for x < -1
            for b in range(-2 * abs(a), -1, abs(a)):
                if abs(b) >= 2:
                    score += abs(b / a)

    return score

# Read input
