    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    # Count prefix frequencies
    prefix_count = {}
    for i in range(n):
        v = a[i]
        count = prefix_count.get(v, 0) + 1
        prefix_count[v] = count

    # Count suffix frequencies
    suffix_count = {}
    for i in range(n-1, -1, -1):
        v = a[i]
        count = suffix_count.get(v, 0) + 1
        suffix_count[v] = count

    # For each unique value, track how many times it appears with each prefix/suffix count
    prefix_map = {}
    for i in range(n):
        v = a[i]
        c = prefix_count[v]
        prefix_map[(v, c)] = prefix_map.get((v, c), 0) + 1

    suffix_map = {}
    for i in range(n):
        v = a[i]
        d = suffix_count[v]
        suffix_map[(v, d)] = suffix_map.get((v, d), 0) + 1

    # Count valid pairs
    result = 0
    # For each prefix count c and suffix count d where c > d
    for (v, c), cnt_c in prefix_map.items():
        for (w, d), cnt_d in suffix_map.items():
            if c > d:
                # These values can form pairs
                result += cnt_c * cnt_d

    print(result)

if __name__ == "__main__":
    solve()
