def solve():
    s = sys.stdin.readline().strip()
    t = sys.stdin.readline().strip()

    n = len(s)

    # Find the first position where s[i] < t[i] AND s[i] + 1 < t[i]
    first_valid = -1
    for i in range(n):
        if s[i] < t[i]:
            # Check if we can increment s[i] and still be less than t[i]
            if ord(s[i]) + 1 < ord(t[i]):
                first_valid = i
                break

    if first_valid == -1:
        # No such string exists
        print("No such string")
    else:
        # Construct the result
        result = list(s)

        # Set the character at first_valid to s[first_valid] + 1
        result[first_valid] = chr(ord(result[first_valid]) + 1)

        # Set all subsequent characters to 'a' (or any character that is strictly less than t's corresponding character)
        for i in range(first_valid + 1, n):
            result[i] = 'a'

        print(''.join(result))

