import sys

def dfs(pos, x, best, n, a, m):
    if pos == n:
        return best

    # Option 1: don't set the current bit
    if dfs(pos + 1, x, best, n, a, m) > best:
        best = dfs(pos + 1, x, best, n, a, m)

    # Option 2: set the current bit if we can
    if (x | (1 << pos)) <= m:
        current_sum = best
        for i in range(pos, n):
            current_sum += a[i]

        if current_sum > best:
            best = current_sum
            best = dfs(pos + 1, x | (1 << pos), best, n, a, m)

    return best


