import sys

sys.setrecursionlimit(1 << 25)

def solve() -> None:
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for _ in range(m):
        u = int(next(it)) - 1
        v = int(next(it)) - 1
        adj[u].append(v)
        adj[v].append(u)

    # Try to 2-color the graph
    color = [-1] * n
    is_bipartite = True

    def dfs(u, c):
        color[u] = c
        for v in adj[u]:
            if color[v] == -1:
                if not dfs(v, 1 - c):
                    return False
            elif color[v] == c:
                return False
        return True

    # Check all connected components
    for i in range(n):
        if color[i] == -1:
            if not dfs(i, 0):
                is_bipartite = False
                break

    if not is_bipartite:
        print(-1)
    else:
        # Output both partitions
        part0 = []
        part1 = []
        for i in range(n):
            if color[i] == 0:
                part0.append(i + 1)
            else:
                part1.append(i + 1)

        print(len(part0))
        print(' '.join(map(str, part0)))
        print(len(part1))
        print(' '.join(map(str, part1)))

if __name__ == "__main__":
    solve()
