    data = input().split()
    idx = 0

    n = int(data[idx]); idx += 1

    # Read cost arrays
    c1 = [int(data[idx + i]) for i in range(n)]
    idx += n
    c2 = [int(data[idx + i]) for i in range(n)]
    idx += n
    c3 = [int(data[idx + i]) for i in range(n)]
    idx += n

    # Read edges
    edges = [[] for _ in range(n)]
    for _ in range(n - 1):
        u = int(data[idx]) - 1
        v = int(data[idx + 1]) - 1
        idx += 2
        edges[u].append(v)
        edges[v].append(u)

    # Check if any vertex has degree > 3
    for i in range(n):
        if len(edges[i]) > 3:
            print(-1)
            return

    # Build adjacency list with parent pointers
    parent = [-1] * n
    children = [[] for _ in range(n)]

    # Use DFS to build tree
    def dfs(u, p):
        parent[u] = p
        for v in edges[u]:
            if v != p:
                children[u].append(v)
                dfs(v, u)

    # Root at vertex 0
    dfs(0, -1)

    # DP: dp[u][color] = minimum cost to color subtree rooted at u with u having color 'color'
    def dp(u, color):
        if u == -1:
            return 0

        # Try all possible colors for children
        cost = 0
        available_colors = []
        for v in children[u]:
            # Child v cannot have the same color as u
            for c in range(1, 4):
                if c != color:
                    sub_cost = dp(v, c)
                    if sub_cost == float('inf'):
                        return float('inf')
                    cost += sub_cost
                    break
            else:
                return float('inf')  # No available color for child

        return cost

    # Try all 3 colors for root
    min_cost = float('inf')
    for color in range(1, 4):
        if dp(0, color) < min_cost:
            min_cost = dp(0, color)
            best_color = color

    # Reconstruct the coloring
    color_array = [0] * n

    def reconstruct(u, parent_color):
        if u == -1:
            return

        # Find a color for u that is different from parent_color and for which we can color children
        for color in range(1, 4):
            if color != parent_color:
                available = True
                for v in children[u]:
                    for c in range(1, 4):
                        if c != color:
                            # Check if we could color this child with color c
                            # We need to ensure the child can be colored with c
                            # Since dp was called with c for child v, we can assume it's possible
                            pass
                # Actually, we need to ensure the child can be colored
                # Let's just try to assign color to u and recursively
                color_array[u] = color
                for v in children[u]:
