import sys

def count_divisors(n):
    """Return the number of divisors of n."""
    if n == 1:
        return 1

    # Trial division to factor n
    factors = {}
    i = 2
    while i * i <= n:
        while n % i == 0:
            factors[i] = factors.get(i, 0) + 1
            n //= i
        i += 1

    if n > 1:
        factors[n] = factors.get(n, 0) + 1

    result = 1
    for exp in factors.values():
        result *= (exp + 1)

    return result

def solve():
    MOD = 998244353
    n = int(sys.stdin.readline())

    result = count_divisors(1)
    for _ in range(n):
        a = int(sys.stdin.readline())
        result = count_divisors(result * a)

    print(result % MOD)

solve()
