    vectors = [tuple(map(int, input().split())) for _ in range(n)]

    memo = {}

    def dist(pos):
        return (pos[0]**2 + pos[1]**2)**0.5

    def is_winning(pos, turn, anton_reflected, dasha_reflected):
        # pos: (x, y)
        # turn: 0 for Anton, 1 for Dasha
        # anton_reflected: bool, whether Anton has used reflection
        # dasha_reflected: bool, whether Dasha has used reflection

        # Check if we're already in a losing position
        if dist(pos) > d:
            return False  # Current player loses

        # Check memoization
        key = (pos[0], pos[1], turn, anton_reflected, dasha_reflected)
        if key in memo:
            return memo[key]

        # Try all possible moves
        for vx, vy in vectors:
            new_x = pos[0] + vx
            new_y = pos[1] + vy

            # Check if this move leads to a losing position for the opponent
            if not is_winning((new_x, new_y), 1 - turn, anton_reflected, dasha_reflected):
                memo[key] = True
                return True

        # Try reflection if available and not already used
        if turn == 0 and not anton_reflected:
            new_x, new_y = pos[1], pos[0]  # Swap x and y
            if not is_winning((new_x, new_y), 1, True, dasha_reflected):
                memo[key] = True
                return True

        if turn == 1 and not dasha_reflected:
            new_x, new_y = pos[1], pos[0]
            if not is_winning((new_x, new_y), 0, anton_reflected, True):
                memo[key] = True
                return True

        # No winning moves found
        memo[key] = False
        return False

    # Start from initial position, Anton's turn, no reflections used
    if is_winning((x, y), 0, False, False):
        print("Anton")
    else:
        print("Dasha")

