def solve() -> None:
    n = int(input())
    strings = [input().strip() for _ in range(n)]

    # Generate all possible rotations for each string
    rotations = []
    for s in strings:
        rots = set()
        for i in range(len(s)):
            rots.add(s[i:] + s[:i])
        rotations.append(rots)

    # Find common rotations
    common_rotations = None
    for r_set in rotations:
        if common_rotations is None:
            common_rotations = r_set
        else:
            common_rotations = common_rotations & r_set

    if not common_rotations:
        print(-1)
        return

    # For each common rotation, calculate the total moves
    # We want to minimize the total moves
    min_total_moves = float('inf')
    for target in common_rotations:
        total_moves = 0
        for i in range(n):
