n = int(input())

if n <= 1:
    print(0)
else:
    # For each possible starting number a with |a| >= 2
    # We can transform to b = a * x where x > 1 and b <= n
    # For each a, we can multiply by the largest factor that fits

    max_score = 0

    for a in range(1, n+1):
        if a < 2:
            continue

        # We can go from a to a*x, a*x*x, etc.
        current = a

        while True:
            # Find the largest factor that fits
            max_multiplier = n // current

            if max_multiplier > 1:
                max_score += max_multiplier
                current *= max_multiplier
            else:
                break

    # Also consider negative numbers
    max_score *= 2

    print(max_score)
