else:
    max_score = 0

    for a in range(1, n+1):
        for b in range(1, n+1):
            if a == b:
                continue

            # Check if we can transform from a to b
            # Either a * x = b with |x| > 1 or b * x = a with |x| > 1

            if b % a == 0:
                x = b // a
                if x > 1 or x < -1:
                    max_score += abs(x)
            elif a % b == 0:
                x = a // b
                if x > 1 or x < -1:
                    max_score += abs(x)

    # Consider negative numbers too
    # Actually, we should consider all numbers in [-n, n] excluding 0
    # Let me reconsider the approach

    # For each number a with 2 ≤ |a| ≤ n, find all b such that |b| divisible by |a|
    max_score = 0

    for a in range(-n, n+1):
        if abs(a) < 2:
            continue

        # Find all multiples of |a|
        abs_a = abs(a)
        for b in range(-n, n+1):
            if abs(b) % abs_a != 0:
                continue
            if b == a:
                continue

            # Check if we can transform
            x = b // a
            if abs(x) > 1:
                max_score += abs(x)

    print(max_score)
