# Count opening and closing brackets
open_types = ['<', '{', '[', '(']
close_types = ['>', '}', ']', ')']

total_open = 0
total_close = 0

# Count total opening and closing brackets
for ch in s:
    if ch in open_types:
        total_open += 1
    elif ch in close_types:
        total_close += 1

# If total number of opening and closing brackets differ, impossible
if total_open != total_close:
    print("Impossible")
else:
    # Greedy approach to find minimum replacements
    committed_open = 0  # Number of opening brackets that have been committed
    replacements = 0

    for ch in s:
        if ch in open_types:
            # This is an opening bracket that needs to match with a closing bracket later
            committed_open += 1
        elif ch in close_types:
            # This is a closing bracket that needs to match with an opening bracket
            if committed_open > 0:
                # We can match this closing bracket with a committed opening bracket
                committed_open -= 1
            else:
                # No matching opening bracket available, need to replace this closing bracket
                replacements += 1

    print(replacements)
