def max_lcm(n):
    if n == 1:
        return 1
    if n == 2:
        return 2
    # n >= 3
    if n % 2 == 1:  # n is odd
        return n * (n - 1) * (n - 2)
    else:  # n is even
        # Compare different combinations
        # 1. n, n-1, n-2
        # 2. n, n-1, n-3
        # 3. n-1, n-2, n-3
        # We need to compute LCMs
        def lcm(a, b):
            return a * b // math.gcd(a, b)

        lcm1 = lcm(n, lcm(n-1, n-2))
        lcm2 = lcm(n, lcm(n-1, n-3))
        lcm3 = lcm(n-1, lcm(n-2, n-3))

        return max(lcm1, lcm2, lcm3)

n = int(input())
print(max_lcm(n))
