import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    t = int(next(it))
    out_lines = []

    for _ in range(t):
        n = int(next(it))
        m = int(next(it))

        # Read n strings
        strings = []
        for _ in range(n):
            s = next(it)
            strings.append(s)

        # For each position, find a character that differs from at most one string
        s = []
        possible_chars = set('abcdefghijklmnopqrstuvwxyz')

        for i in range(m):
            # Try each possible character for position i
            found = False
            for c in possible_chars:
                # Count how many strings differ from c at position i
                count_diff = 0
                for j in range(n):
                    if strings[j][i] != c:
                        count_diff += 1
                        if count_diff > 1:
                            break

                if count_diff <= 1:
                    s.append(c)
                    found = True
                    break

            if not found:
                # No character works at this position
                out_lines.append("-1")
                break

        else:
            # All positions found
            out_lines.append(''.join(s))

    sys.stdout.write('\n'.join(out_lines))

if __name__ == '__main__':
    solve()
