    min_changes = float('inf')

    # Try all possible starting positions in s
    for i in range(len(s) - k + 1):
        # Try all 3 possible starting characters in the infinite pattern
        for start_char in ['R', 'G', 'B']:
            # Build the pattern of length k
            pattern = []
            for j in range(k):
                # Position in the infinite pattern: (i + j) % 3
                # If (i + j) % 3 == 0 → 'R', else if (i + j) % 3 == 1 → 'G', else 'B'
                if (i + j) % 3 == 0:
                    pattern.append('R')
                elif (i + j) % 3 == 1:
