import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    arr = list(map(int, data[1:1 + 2*n - 1]))

    # Strategy: flip the n elements with the largest absolute values if they are negative
    # Sort by absolute value descending
    arr.sort(key=lambda x: abs(x), reverse=True)

    # Flip the first n elements if they are negative
    for i in range(min(n, len(arr))):
        if arr[i] < 0:
            arr[i] = -arr[i]

    print(sum(arr))

if __name__ == "__main__":
    solve()
"}

