def solve(s):
    chars = list(s)

    while True:
        # Apply operation 1: find first 'yx' and swap to 'xy'
        op1_idx = -1
        for i in range(len(chars) - 1):
            if chars[i] == 'y' and chars[i+1] == 'x':
                op1_idx = i
                break

        # Apply operation 2: find first 'xy' and remove
        op2_idx = -1
        for i in range(len(chars) - 1):
            if chars[i] == 'x' and chars[i+1] == 'y':
                op2_idx = i
                break

        # Check if any operation can be applied
        if op1_idx == -1 and op2_idx == -1:
            break

        # Apply the appropriate operation
        if op1_idx != -1:
            # Swap 'yx' to 'xy'
            chars[op1_idx], chars[op1_idx+1] = chars[op1_idx+1], chars[op1_idx]
        else:
            # Remove 'xy'
            chars.pop(op2_idx)
            chars.pop(op2_idx)

    return ''.join(chars)

if __name__ == '__main__':
    s = sys.stdin.readline().strip()
    print(solve(s))
