    for _ in range(t):
        n, m = map(int, sys.stdin.readline().split())
        strings = []
        for _ in range(n):
            strings.append(sys.stdin.readline().strip())

        # Try each position
        for j in range(m):
            # Try each character for this position
            for c in 'abcdefghijklmnopqrstuvwxyz':
                # Create candidate string
                s = list(strings[0])
                s[j] = c
                s = ''.join(s)

                # Check if this works for all strings
                valid = True
                for string in strings:
                    diff = 0
                    for i in range(m):
                        if s[i] != string[i]:
                            diff += 1
                            if diff > 1:
                                valid = False
                                break
                    if not valid:
                        break

                if valid:
                    print(s)
                    break
            else:
                continue
            break
        else:
            print("-1")

