# Check if all characters in s2 exist in s1
if not set(s2).issubset(set(s1)):
    print(-1)
else:
    # Create a dictionary to map characters to their positions in s1
    char_positions = {char: idx for idx, char in enumerate(s1)}

    count = 1  # We need at least one copy
    current_pos = 0

    for char in s2:
        # Find where this character appears in s1
        # We need to find the position after current_pos
        next_pos = None
        for i in range(current_pos, len(s1)):
            if s1[i] == char:
                next_pos = i
                break

        if next_pos is None:
            # Need another copy of s1
            count += 1
            current_pos = 0
            # Find the first occurrence of this character in the new copy
            for i in range(len(s1)):
                if s1[i] == char:
                    current_pos = i
                    break
        else:
            current_pos = next_pos

    print(count)
