# Read input
n = int(input())
x = int(input())

# If n is even, the last move swapped 1 and 2. If n is odd, the last move swapped 0 and 1.
# To trace back, we need to reverse the moves from the final position x.

# If n is even, we just return x (no need to trace back because the last move doesn't affect the result)
# If n is odd, we need to trace back through all moves
if n % 2 == 0:
    print(x)
else:
    # Trace back through all moves
    position = x
    for i in range(n, 0, -1):
        if i % 2 == 1:  # odd move: swap 0 and 1
            if position == 0:
                position = 1
            elif position == 1:
                position = 0
        else:  # even move: swap 1 and 2
            if position == 1:
                position = 2
            elif position == 2:
                position = 1
    print(position)
