def is_regular_bracket_sequence(s):
    """Check if string s is a regular bracket sequence"""
    stack = []
    for ch in s:
        if ch in "([{":
            stack.append(ch)
        else:
            if not stack:
                return False
            top = stack.pop()
            if (top == "(" and ch != ")") or (top == "[" and ch != "]") or (top == "{" and ch != "}"):
                return False
    return len(stack) == 0

# For this problem, we just need to count replacements
# Let me think about a simpler approach

def count_replacements(s):
    n = len(s)
    if n % 2 != 0:
        return "Impossible"

    # Track which brackets are used
    used = [False] * n

    # For opening brackets at index i, find closest unmatched closing bracket at index > i
    for i in range(n):
        if s[i] in "([{":
            # Find closest unmatched closing bracket
            for j in range(i + 1, n):
                if not used[j] and s[j] not in "([{":
                    used[j] = True
                    break

    # For closing brackets at index i, find closest unmatched opening bracket at index < i
    for i in range(n):
        if s[i] not in "([{":
            # Find closest unmatched opening bracket
            for j in range(i):
                if not used[j] and s[j] in "([{":
                    used[j] = True
                    break

    # Count mismatches
    mismatch_count = 0
    for i in range(n):
        if used[i]:
            # Check if the current character matches the expected type
            # For opening brackets, expected is opening
            # For closing brackets, expected is closing
            # We need to check if they match
            expected = s[i] if s[i] in "([{" else s[i]
            if (s[i] == "<" and expected != "><" and expected != "{"") or \n               (s[i] == ">" and expected != "<" and expected != ">") or \n               (s[i] == "{" and expected != "{" and expected != "["") or \n               (s[i] == "}" and expected != "{" and expected != "}") or \n               (s[i] == "[" and expected != "[" and expected != "]") or \n               (s[i] == "]" and expected != "[" and expected != "]") or \n               (s[i] == "(" and expected != "(" and expected != ")") or \n               (s[i] == ")" and expected != "(" and expected != ")"):
                mismatch_count += 1

    return mismatch_count

