import sys
from collections import Counter

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+2*n]))

    # Count frequencies
    freq = Counter(a)

    # Check if any element has odd frequency
    has_odd = any(count % 2 == 1 for count in freq.values())

    if not has_odd:
        print(-1)
        return

    # Find which element has odd frequency
    odd_element = next(key for key, count in freq.items() if count % 2 == 1)

    # Create result
    result = []

    # First half: place one odd element and distribute others
    first_half = [odd_element]
    second_half = []

    # Distribute remaining elements
    for i in range(len(a)):
        if a[i] == odd_element:
            if len(first_half) == n:
                second_half.append(a[i])
            else:
                first_half.append(a[i])
        else:
            if len(first_half) < n:
                first_half.append(a[i])
            else:
                second_half.append(a[i])

    result = first_half + second_half

    # Ensure we only have n elements in each half
    if len(result) > 2*n:
        result = result[:2*n]

    print(' '.join(map(str, result)))

if __name__ == "__main__":
    solve()
