def max_score(n):
    """Find the maximum score by transforming integers from -n to n.
    """

    # Create a graph of integers from -n to n (excluding 0)
    graph = {}

    # Build adjacency list
    for a in range(-n, n + 1):
        if abs(a) == 0:
            continue

        graph[a] = []

        # Try multiplying by integers > 1
        for k in range(2, n + 1):
            b = a * k
            if -n <= b <= n:
                graph[a].append((b, k))  # weight is |k|

        # Try dividing by integers > 1
        for k in range(2, n + 1):
            if a % k == 0:
                b = a // k
                if abs(b) >= 2:
                    graph[a].append((b, k))  # weight is |k|


    # Use DFS to find maximum score path
    def dfs(node, visited):
        if node in visited:
            return 0
        visited.add(node)

        max_score = 0
        for neighbor, weight in graph[node]:
            next_score = dfs(neighbor, visited)
            max_score = max(max_score, weight + next_score)

        visited.remove(node)
        return max_score

    # Try starting from each integer
    max_total = 0
    for start in range(-n, n + 1):
        if abs(start) == 0:
            continue

        visited = set()
        total = dfs(start, visited)
        max_total = max(max_total, total)

    return max_total

