                graph[a].append((b, k))  # weight is |k|

        # Try dividing by integers > 1
        for k in range(2, n + 1):
            if a % k == 0:
                b = a // k
                if abs(b) >= 2:
                    graph[a].append((b, k))  # weight is |k|

    # Use DFS to find maximum score path
    def dfs(node, visited):
        # If no edges from node, return 0
        if not graph[node]:
            return 0

        max_score = 0
        for neighbor, weight in graph[node]:
            # If we haven't visited this neighbor yet, go there
            if neighbor not in visited:
                new_visited = visited.copy()
                new_visited.add(neighbor)

                # Score is weight + score from neighbor to max score path
                max_score = max(max_score, weight + dfs(neighbor, new_visited))

        return max_score

    # Try starting from each integer
    max_total = 0
    for start in range(-n, n + 1):
        if abs(start) == 0:
            continue

        visited = {start}
        total = dfs(start, visited)
        max_total = max(max_total, total)

    return max_total

