def find_initial_position(n: int, x: int) -> int:
    """Find the initial position of the ball."""
    position = x

    # Work backwards through the moves
    for move in range(n, 0, -1):
        if move % 2 == 1:  # Odd move: swap 0 and 1
            if position == 0:
                position = 1
            elif position == 1:
                position = 0
        else:  # Even move: swap 1 and 2
            if position == 1:
                position = 2
            elif position == 2:
                position = 1

