from collections import Counter

n = input().strip()

digits = [int(c) for c in n]

# Count frequency of each digit
freq = Counter(digits)

result = 0

# For each possible length (from 1 to len(n))
for length in range(1, len(digits) + 1):
    # We need to count permutations of a multiset of length digits
    # This is complex - let me think about it differently

    # For each position, we can choose any digit from n such that
    # we don't go over the frequency
    # and we don't start with 0

    # Let me try a recursive approach with memoization

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def count(length, has_zero):
        if length == 0:
            return 1

        total = 0
        for digit in range(10):
            if has_zero:
                # If we've already had a 0 in the number,
                # we can choose any digit
                if freq[digit] > 0:
                    new_has_zero = has_zero
                    if digit == 0:
                        new_has_zero = True
                    total += count(length - 1, new_has_zero)
            else:
                # If we haven't had a 0 yet,
                # we can't choose 0 as the first digit
                if freq[digit] > 0:
                    new_has_zero = has_zero
                    if digit == 0:
                        new_has_zero = True
                    else:
                        # We haven't started yet, so we need to avoid 0
                        if digit == 0:
                            continue
                    total += count(length - 1, new_has_zero)
        return total

    # Start with no zero and length from 1 to len(n)
    for l in range(1, len(digits) + 1):
        result += count(l, False)

print(result)
