def is_good(arr):
    """Check if the sequence forms a good sequence."""
    n = len(arr)
    if n < 2:
        return False

    # Calculate minimum XOR for each element
    min_xor = [float('inf')] * n
    min_j = [-1] * n

    for i in range(n):
        for j in range(n):
            if i != j:
                xor = arr[i] ^ arr[j]
                if xor < min_xor[i]:
                    min_xor[i] = xor
                    min_j[i] = j

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for i, j in enumerate(min_j):
        if j != -1:
            adj[i].append(j)
            adj[j].append(i)

    # Check if the graph is connected
    visited = [False] * n
    def dfs(u):
        visited[u] = True
        for v in adj[u]:
            if not visited[v]:
                dfs(v)

    dfs(0)

    # If all nodes are visited, it's connected
    return sum(visited) == n

