    import sys
    data = sys.stdin.read().split()
    if not data:
        return
    idx = 0

    while idx < len(data):
        N = int(data[idx])
        idx += 1

        if N == 0:
            break

        # Read contamination grid
        grid = []
        for _ in range(N):
            row = data[idx]
            idx += 1
            grid.append(row)

        # Find vertices by looking for cells with contamination level 3
        # If a cell has contamination level 3, 3 corners are on the polygon
        # The missing corner should be the one adjacent to a vertex

        vertices = set()

        for y in range(N):
            for x in range(N):
                if grid[y][x] == '3':
                    # Check which corner is missing
                    missing = None
                    for dx, dy in [(0, 0), (1, 0), (0, 1), (1, 1)]:
                        cx = x + dx
                        cy = y + dy
                        if (cx, cy) not in vertices:
                            # If the point is not a vertex yet, it might be the missing corner
                            if all((x2, y2) in vertices for x2, y2 in corners_from_cell(cx, cy, dx, dy, grid)):
                                missing = (cx, cy)
                                break
                    if missing is not None:
                        vertices.add(missing)

        # Sort lexicographically
        sorted_vertices = sorted(vertices)

        # Output
        print(len(sorted_vertices))
        for (x, y) in sorted_vertices:
            print(f"{x} {y}")

# Helper to get corners of a cell
def corners_from_cell(x, y, dx, dy, grid):
    if grid[y][x] != '4':
        return []
    return [(x, y), (x + 1, y), (x, y + 1), (x + 1, y + 1)]

