B = list(map(int, input().split()))

# dp_greater: ways where A > B up to current position
# dp_equal: ways where A == B up to current position
# dp_less: ways where A < B up to current position

dp_greater = 0
dp_equal = 1
dp_less = 0

for i in range(n):
    a = A[i]
    b = B[i]

    # For each position, we need to consider all possible values
    # that can replace erased symbols (0)

    # Count how many (x, y) pairs satisfy A > B, A == B, A < B
    count_greater = 0
    count_equal = 0
    count_less = 0

    # Total possibilities for this position
    total = 1

    if a == 0 and b == 0:
        total = m * m
        for x in range(1, m + 1):
            for y in range(1, m + 1):
                if x > y:
                    count_greater += 1
                elif x == y:
                    count_equal += 1
                else:
                    count_less += 1
    elif a == 0:
        total = m
        for x in range(1, m + 1):
            if x > b:
                count_greater += 1
            elif x == b:
                count_equal += 1
            else:
                count_less += 1
    elif b == 0:
        total = m
        for y in range(1, m + 1):
            if a > y:
                count_greater += 1
            elif a == y:
                count_equal += 1
            else:
                count_less += 1
    else:
        # both fixed
        total = 1
        if a > b:
            count_greater = 1
        elif a < b:
            count_less = 1
        else:
            count_equal = 1

    # Update dp arrays
    # dp_greater_new = dp_greater * total (ways from previous > continue)
    # dp_greater_new += dp_equal * count_greater (ways from previous = become >)
    # dp_greater_new += dp_less * count_greater (ways from previous < become >)

    dp_greater = (dp_greater * total + dp_equal * count_greater + dp_less * count_greater) % MOD
    dp_equal = (dp_equal * count_equal) % MOD
    dp_less = (dp_less * total + dp_equal * count_less + dp_less * count_less) % MOD

