import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    # Sort the array
    a.sort()

    # Build the graph
    edges = set()
    for i in range(n):
        min_xor = float('inf')
        min_idx = -1
        for j in range(n):
            if i == j:
                continue
            xor_val = a[i] ^ a[j]
            if xor_val < min_xor:
                min_xor = xor_val
                min_idx = j
        # Connect i to min_idx
        if min_idx != -1 and min_idx != i:
            edges.add((min_idx, i))

    # Check if it's a tree
    # A tree must have exactly n-1 edges
    if len(edges) != n - 1:
        print(n - 1)
    else:
        # Check connectivity (BFS/DFS)
        visited = [False] * n
        queue = [0]
        visited[0] = True
        count = 1

        while queue:
            node = queue.pop(0)
            for neighbor in [i for i in range(n) if (node, i) in edges]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    count += 1
                    queue.append(neighbor)

        if count == n:
            print(0)
        else:
            print(n - count)

