    edges = [[] for _ in range(n + 1)]

    for i in range(2, 2 + 2 * m, 2):
        u = int(data[i])
        v = int(data[i + 1])
        edges[u].append(v)
        edges[v].append(u)

    # Check if graph is bipartite
    color = [-1] * (n + 1)
    is_bipartite = True

    def dfs(v, c):
        nonlocal is_bipartite
        color[v] = c
        for u in edges[v]:
            if color[u] == -1:
                if not dfs(u, 1 - c):
                    return False
            elif color[u] == color[v]:
                is_bipartite = False
                return False
        return True

    for v in range(1, n + 1):
