    x, y, n, d = map(int, input().split())
    vectors = []
    for _ in range(n):
        vx, vy = map(int, input().split())
        vectors.append((vx, vy))

    # Function to calculate distance squared
    def dist_sq(x, y):
        return x*x + y*y

    # Check if a state is losing (distance > d)
    def is_losing(x, y):
        return dist_sq(x, y) > d * d

    # State: (x, y, anton_reflected, dasha_reflected, is_anton_turn)
    # Value: 0 for losing, 1 for winning
    visited = {}

