def distance(x, y):
    return (x*x + y*y) ** 0.5

def solve():
    x, y, n, d = map(int, input().split())
    vectors = [tuple(map(int, input().split())) for _ in range(n)]

    memo = {}

    def can_win(pos, reflection_used):
        # pos = (x, y), reflection_used = bool
        if (pos, reflection_used) in memo:
            return memo[(pos, reflection_used)]

        x_curr, y_curr = pos

        # Check if current position is already losing
        if distance(x_curr, y_curr) > d:
            # This position is already losing
            return False

        # Try all vectors
        for dx, dy in vectors:
            new_x = x_curr + dx
            new_y = y_curr + dy

            # Check if this move is valid (doesn't immediately cause loss)
            if distance(new_x, new_y) <= d:
                # Opponent's turn
                if not can_win((new_x, new_y), reflection_used):
                    # Opponent cannot win from this position
                    memo[(pos, reflection_used)] = True
                    return True

        # Try reflection (if not used yet)
        if not reflection_used:
            new_x, new_y = y_curr, x_curr

            # Check if this move is valid
            if distance(new_x, new_y) <= d:
                # Opponent's turn
                if not can_win((new_x, new_y), True):
                    memo[(pos, reflection_used)] = True
                    return True

        # All moves lead to opponent winning
        memo[(pos, reflection_used)] = False
        return False

    # Initial position: (x, y), reflection not used
    if can_win((x, y), False):
        print("Anton")
    else:
        print("Dasha")

