import sys

def find(parent, x):
    if parent[x] != x:
        parent[x] = find(parent, parent[x])
    return parent[x]

def union(parent, rank, x, y):
    px = find(parent, x)
    py = find(parent, y)
    if px == py:
        return False
    if rank[px] < rank[py]:
        parent[px] = py
    elif rank[px] > rank[py]:
        parent[py] = px
    else:
        parent[py] = px
        rank[px] += 1
    return True

n, m = map(int, sys.stdin.readline().split())
edges = []
for i in range(m):
    a, b, e = map(int, sys.stdin.readline().split())
    edges.append((e, a, b, i))

# Sort edges by weight
edges.sort()

# Kruskal's algorithm to find MST
parent = list(range(n + 1))
rank = [1] * (n + 1)

# Store MST edges
mst_edges = []
for edge in edges:
    e, a, b, idx = edge
    if union(parent, rank, a, b):
        mst_edges.append((a, b, e, idx))

# Build edge weight map
edge_weight = {}
for a, b, e, idx in mst_edges:
    edge_weight[idx] = e

# Build parent array for path tracing
mst_parent = [0] * (n + 1)
for a, b, e, idx in mst_edges:
    mst_parent[a] = b
    mst_parent[b] = a

# Function to trace path from u to v and find max edge weight
def get_max_edge_on_path(u, v):
    max_weight = 0
    # Trace from u up to root
    while mst_parent[u] != 0:
        max_weight = max(max_weight, edge_weight.get(mst_parent[u], 0))
        u = mst_parent[u]
    # Trace from v up to root
    while mst_parent[v] != 0:
        max_weight = max(max_weight, edge_weight.get(mst_parent[v], 0))
        v = mst_parent[v]
    return max_weight

# For each edge not in MST, compute E_max
for edge in edges:
    e, a, b, idx = edge
    if idx not in edge_weight:
        max_e = get_max_edge_on_path(a, b)
        print(max_e)
