def compute_max_lcm(n):
    if n == 1:
        return 1
    if n == 2:
        return 2
    if n == 3:
        return 3

    if n % 2 == 1:  # odd
        return n * (n - 1) * (n - 2)
    else:  # even
        if n % 3 != 0:
            return n * (n - 1) * (n - 2)
        else:
            # If n is divisible by 3, we need to be careful
            # Let's check n, n-1, n-3
            # But also consider n-2, n-1, n-3 if LCM is better
            # For now, let's just use n * (n-1) * (n-3)
            return n * (n - 1) * (n - 3)

n = int(input())
print(compute_max_lcm(n))
