def generate_super_lucky(length):
    """Generate all super lucky numbers of a given length"""
    half = length // 2
    # Generate all combinations of positions for 4s
    for indices in combinations(range(length), half):
        # Create the number
        number = ['7'] * length
        for i in indices:
