import sys

def solve(s):
    while True:
        # Try to apply operation 1 (swap 'yx' to 'xy')
        swapped = False
        for i in range(len(s) - 1):
            if s[i] == 'y' and s[i+1] == 'x':
                # Swap them
                s = s[:i] + 'xy' + s[i+2:]
                swapped = True
                # After swapping, restart the search from the beginning
                break

        if not swapped:
            # Try to apply operation 2 (remove 'xy')
            removed = False
            for i in range(len(s) - 1):
                if s[i] == 'x' and s[i+1] == 'y':
                    # Remove them
                    s = s[:i] + s[i+2:]
                    removed = True
                    # After removing, restart the search from the beginning
                    break

            if not removed:
                # No more operations can be applied
                return s

if __name__ == '__main__':
    s = sys.stdin.readline().strip()
    print(solve(s))
