import sys

def solve():
    s = list(sys.stdin.read().strip())

    while True:
        # Operation 1: find first "yx" and swap to "xy"
        op1_pos = -1
        for i in range(len(s) - 1):
            if s[i] == 'y' and s[i+1] == 'x':
                op1_pos = i
                break

        if op1_pos != -1:
            # Apply operation 1
            s[op1_pos], s[op1_pos + 1] = s[op1_pos + 1], s[op1_pos]
            continue

        # Operation 2: find first "xy" and remove both
        op2_pos = -1
        for i in range(len(s) - 1):
            if s[i] == 'x' and s[i+1] == 'y':
                op2_pos = i
                break

        if op2_pos != -1:
            # Apply operation 2
            del s[op2_pos:op2_pos+2]
            continue

        # Neither operation can be applied
        break

    print(''.join(s))

if __name__ == "__main__":
    solve()
