for _ in range(q):
    n, k = map(int, input().split())
    s = input()

    min_changes = float('inf')

    # Try each of the 3 possible patterns
    for pattern in ["RGB", "GBR", "BRG"]:
        # Try each starting position in s
        for i in range(n - k + 1):
            changes = 0
            # Compare substring with pattern
            for j in range(k):
                if s[i+j] != pattern[j % 3]:
                    changes += 1
            min_changes = min(min_changes, changes)

    print(min_changes)
